#!/usr/bin/env bash
# platform-signatures-test.sh: offline gate for the platform (binary) tarball signatures of contract plugins.release-signature v1.1
# (P7-PLUG-83). Every key here is a THROWAWAY Ed25519 key generated by this script; no real key is read, nothing is uploaded, no key
# text is printed. It covers, with scripts/release/sign.sh as the signer and scripts/release/verify-signatures.sh as the verifier:
#   - a platform signature is accepted for its slug, version, platform and bytes and for nothing else (moved platform, version, slug,
#     flipped byte, source signature used as platform signature and the reverse, missing signature, orphan signature);
#   - the three-argument form of sign.sh is still the v1 source signature, and both messages equal what openssl signs directly;
#   - the same release directory fails against every key committed in scripts/release/keys/;
#   - platform-built-check.sh passes tarballs this run built and refuses a replaced, renamed or unlisted one;
#   - the committed interop fixture scripts/release/testdata/platform-v1/ (made by sign.sh, consumed by the cli Ticket P7-PLUG-84)
#     still verifies and its vectors still hold.
# Run from any directory: bash scripts/release/platform-signatures-test.sh   (OPENSSL=/path/to/openssl3 if the default is LibreSSL)
# Regenerate the committed fixture (new throwaway key, the private half is discarded): bash scripts/release/platform-signatures-test.sh --regen-testdata
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="$(cd "$HERE/../.." && pwd)"
O="${OPENSSL:-openssl}"
"$O" version 2>/dev/null | grep -q '^OpenSSL ' || { echo "FAIL: $O is not OpenSSL (set OPENSSL)"; exit 1; }
command -v jq >/dev/null 2>&1 || { echo "FAIL: jq not found"; exit 1; }
T="$(mktemp -d "${TMPDIR:-/tmp}/platsig.XXXXXX")"
trap 'rm -rf "$T"' EXIT

sha256_file() { if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1; else shasum -a 256 "$1" | cut -d' ' -f1; fi; }

# --- throwaway key -------------------------------------------------------------------------------------------------------
umask 077
"$O" genpkey -algorithm ed25519 -out "$T/key.pem" 2>/dev/null
"$O" pkey -in "$T/key.pem" -pubout -out "$T/test.pub" 2>/dev/null
ID="plugins-$("$O" pkey -in "$T/key.pem" -pubout -outform DER 2>/dev/null | tail -c 32 | { sha256sum 2>/dev/null || shasum -a 256; } | cut -c1-16)"
umask 022
sign() { NSELF_RELEASE_SIGNING_KEY_FREE="$(cat "$T/key.pem")" NSELF_RELEASE_SIGNING_KEY_FREE_ID="$ID" OPENSSL="$O" bash "$HERE/sign.sh" "$@"; }

# --- a good release directory ----------------------------------------------------------------------------------------------
# mktar OUT STUBTEXT: deterministic tarball of one stub file nself-demo (never a real build).
mktar() {
  local out="$1" d
  d="$(mktemp -d "$T/stub.XXXXXX")"
  printf '%s\n' "$2" > "$d/nself-demo"
  chmod 755 "$d/nself-demo"
  bash "$REPO/scripts/deterministic-tar.sh" "$out" -C "$d" nself-demo
}
# build_release DIR SLUG VERSION: source tarball plus linux-amd64 and darwin-arm64 binary tarballs, all signed, releases.json.
build_release() {
  local dir="$1" slug="$2" ver="$3" src plin pdar
  mkdir -p "$dir"
  src="$dir/$slug-$ver.tar.gz"; plin="$dir/$slug-$ver-linux-amd64.tar.gz"; pdar="$dir/$slug-$ver-darwin-arm64.tar.gz"
  mktar "$src" "source of $slug $ver"
  mktar "$plin" "stub binary $slug $ver linux-amd64"
  mktar "$pdar" "stub binary $slug $ver darwin-arm64"
  jq -nc --arg s "$slug" --arg v "$ver" \
    --arg ssha "$(sha256_file "$src")" --argjson ssig "$(sign "$slug" "$ver" "$src")" \
    --arg lsha "$(sha256_file "$plin")" --argjson lsig "$(sign "$slug" "$ver" "$plin" linux-amd64)" \
    --arg dsha "$(sha256_file "$pdar")" --argjson dsig "$(sign "$slug" "$ver" "$pdar" darwin-arm64)" \
    '{schema_version: 1, releases: {($s): {version: $v, sha256: $ssha, release_signature: $ssig,
      platform_checksums: {"linux-amd64": $lsha, "darwin-arm64": $dsha},
      platform_signatures: {"linux-amd64": $lsig, "darwin-arm64": $dsig}}}}' > "$dir/releases.json"
}
GOOD="$T/good"
build_release "$GOOD" demo 1.2.3

# --- tiny harness ----------------------------------------------------------------------------------------------------------
fails=0
pass() { echo "ok   $1"; }
fail() { echo "FAIL $1"; fails=$((fails + 1)); }
verify() { bash "$HERE/verify-signatures.sh" --pub "${2:-$T/test.pub}" "$1"; }
# expect_ok LABEL DIR: verify-signatures accepts DIR with the throwaway key.
expect_ok() { local out; if out="$(verify "$2" 2>&1)"; then pass "$1"; else fail "$1 (rejected: $out)"; fi; }
# expect_refused LABEL NEEDLE DIR: verify-signatures rejects DIR and says NEEDLE.
expect_refused() {
  local out
  if out="$(verify "$3" 2>&1)"; then fail "$1 (accepted)"; return; fi
  case "$out" in *"$2"*) pass "$1" ;; *) fail "$1 (rejected, but not with '$2': $out)" ;; esac
}
# variant NAME JQ_FILTER: copy GOOD to $T/NAME and edit its releases.json with the jq filter.
variant() { rm -rf "${T:?}/$1"; cp -R "$GOOD" "$T/$1"; jq -c "$2" "$GOOD/releases.json" > "$T/$1/releases.json"; }

expect_ok "good release (source + 2 platform signatures)" "$GOOD"
case "$(verify "$GOOD" 2>&1)" in *"verified 1 source tarball(s) and 2 binary tarball(s) (checksum + signature each)"*) pass "summary counts source and binary apart" ;; *) fail "summary line" ;; esac

# --- tamper cases ------------------------------------------------------------------------------------------------------------
rm -rf "$T/flip"; cp -R "$GOOD" "$T/flip"
printf 'x' >> "$T/flip/demo-1.2.3-linux-amd64.tar.gz"
expect_refused "flipped byte in a platform tarball" "checksum mismatch: demo-1.2.3-linux-amd64.tar.gz" "$T/flip"

# The attacker also rewrites platform_checksums to match the new bytes: the signature, not the checksum, must stop it.
rm -rf "$T/flipfix"; cp -R "$GOOD" "$T/flipfix"
printf 'x' >> "$T/flipfix/demo-1.2.3-linux-amd64.tar.gz"
jq -c --arg sha "$(sha256_file "$T/flipfix/demo-1.2.3-linux-amd64.tar.gz")" '.releases.demo.platform_checksums["linux-amd64"] = $sha' "$GOOD/releases.json" > "$T/flipfix/releases.json"
expect_refused "tampered bytes with a rewritten checksum" "platform signature mismatch: demo 1.2.3 linux-amd64" "$T/flipfix"

variant swapped '.releases.demo.platform_signatures |= {"linux-amd64": .["darwin-arm64"], "darwin-arm64": .["linux-amd64"]}'
expect_refused "signature moved to another platform" "platform signature mismatch: demo 1.2.3 linux-amd64" "$T/swapped"

# Same bytes, claimed as another version: rename the files and the row; every signature was made for 1.2.3.
rm -rf "$T/ver"; mkdir "$T/ver"
for f in "$GOOD"/demo-1.2.3*.tar.gz; do cp "$f" "$T/ver/$(basename "$f" | sed 's/1\.2\.3/1.2.4/')"; done
jq -c '.releases.demo.version = "1.2.4"' "$GOOD/releases.json" > "$T/ver/releases.json"
expect_refused "signature moved to another version" "platform signature mismatch: demo 1.2.4 linux-amd64" "$T/ver"

rm -rf "$T/slug"; mkdir "$T/slug"
for f in "$GOOD"/demo-1.2.3*.tar.gz; do cp "$f" "$T/slug/$(basename "$f" | sed 's/^demo-/other-/')"; done
jq -c '.releases = {other: .releases.demo}' "$GOOD/releases.json" > "$T/slug/releases.json"
expect_refused "signature moved to another slug" "platform signature mismatch: other 1.2.3 linux-amd64" "$T/slug"

variant srcaspl '.releases.demo.platform_signatures["linux-amd64"] = .releases.demo.release_signature'
expect_refused "source signature used as a platform signature" "platform signature mismatch: demo 1.2.3 linux-amd64" "$T/srcaspl"

variant plasrc '.releases.demo.release_signature = .releases.demo.platform_signatures["linux-amd64"]'
expect_refused "platform signature used as the source signature" "signature mismatch: demo 1.2.3" "$T/plasrc"

variant nosig1 'del(.releases.demo.platform_signatures["linux-amd64"])'
expect_refused "one platform tarball with no signature" "unsigned platform: demo 1.2.3 linux-amd64" "$T/nosig1"
variant nosigall 'del(.releases.demo.platform_signatures)'
expect_refused "no platform signatures on a signed row" "unsigned platform: demo 1.2.3 darwin-arm64" "$T/nosigall"
variant badshape '.releases.demo.platform_signatures["linux-amd64"] = "not-an-object"'
expect_refused "platform signature of the wrong shape" "platform signature mismatch: demo 1.2.3 linux-amd64" "$T/badshape"
variant badalg '.releases.demo.platform_signatures["linux-amd64"].alg = "rsa"'
expect_refused "platform signature with another algorithm" "platform signature mismatch: demo 1.2.3 linux-amd64" "$T/badalg"
variant badkid '.releases.demo.platform_signatures["linux-amd64"].key_id = "plugins-0000000000000000"'
expect_refused "platform signature naming another key" "platform signature mismatch: demo 1.2.3 linux-amd64" "$T/badkid"
variant orphan '.releases.demo.platform_signatures["windows-amd64"] = .releases.demo.platform_signatures["linux-amd64"]'
expect_refused "platform signature without a platform checksum" "orphan platform signature: demo 1.2.3 windows-amd64" "$T/orphan"
variant orphanrow '.releases.demo.release_signature = null'
expect_refused "platform signatures on an unsigned row" "orphan platform signature: demo 1.2.3 linux-amd64" "$T/orphanrow"

# A binary tarball dropped from the directory is a failure, not a smaller set.
rm -rf "$T/dropped"; cp -R "$GOOD" "$T/dropped"; rm "$T/dropped/demo-1.2.3-darwin-arm64.tar.gz"
expect_refused "platform tarball removed" "missing tarball: demo-1.2.3-darwin-arm64.tar.gz" "$T/dropped"

# --- the committed keys must refuse the throwaway signatures -------------------------------------------------------------------
n=0
for k in "$HERE"/keys/*.pub; do
  [ -e "$k" ] || continue
  n=$((n + 1))
  if verify "$GOOD" "$k" >/dev/null 2>&1; then fail "throwaway signatures verify against committed key $(basename "$k")"; else pass "committed key $(basename "$k") refuses them"; fi
done
[ "$n" -gt 0 ] || fail "no committed key found under scripts/release/keys/ to test against"

# --- sign.sh itself ----------------------------------------------------------------------------------------------------------
# Independent re-implementation of both messages: openssl signs them directly; Ed25519 is deterministic, so the bytes must match.
SRC="$GOOD/demo-1.2.3.tar.gz"; PLIN="$GOOD/demo-1.2.3-linux-amd64.tar.gz"
direct_sig() { printf "$1" > "$T/direct.msg"; "$O" pkeyutl -sign -rawin -inkey "$T/key.pem" -in "$T/direct.msg" -out "$T/direct.sig" 2>/dev/null; "$O" base64 -A -in "$T/direct.sig"; }
want_src="$(direct_sig "nself-plugin-v1\ndemo\n1.2.3\n$(sha256_file "$SRC")\n")"
want_bin="$(direct_sig "nself-plugin-bin-v1\ndemo\n1.2.3\nlinux-amd64\n$(sha256_file "$PLIN")\n")"
[ "$(sign demo 1.2.3 "$SRC" | jq -r .sig)" = "$want_src" ] && pass "three-argument form signs the v1 source message" || fail "three-argument form changed"
[ "$(sign demo 1.2.3 "$PLIN" linux-amd64 | jq -r .sig)" = "$want_bin" ] && pass "PLATFORM form signs the nself-plugin-bin-v1 message" || fail "platform message differs from the contract"
[ "$want_src" != "$want_bin" ] && pass "the two domains give different signatures" || fail "domains collide"
sign demo 1.2.3 "$PLIN" linux-amd64 | jq -e '.alg == "ed25519" and .key_id == "'"$ID"'" and (.sig | length) == 88' >/dev/null && pass "platform signature object has the release_signature shape" || fail "platform signature shape"
for bad in "" linux darwin-x64 LINUX-AMD64 "linux-amd64 " windows; do
  rc=0; sign demo 1.2.3 "$PLIN" "$bad" >/dev/null 2>&1 || rc=$?
  [ "$rc" = 2 ] && pass "sign.sh refuses platform '$bad' with exit 2" || fail "sign.sh platform '$bad' exit $rc"
done
rc=0; sign demo 1.2.3 "$PLIN" linux-amd64 extra >/dev/null 2>&1 || rc=$?
[ "$rc" = 2 ] && pass "sign.sh refuses a fifth argument" || fail "sign.sh fifth argument exit $rc"

# --- platform-built-check.sh -------------------------------------------------------------------------------------------------
BIN="$T/binstage"; mkdir -p "$BIN"
cp "$PLIN" "$GOOD/demo-1.2.3-darwin-arm64.tar.gz" "$BIN/"
BUILT="$T/built.txt"; (cd "$BIN" && sha256sum -- *.tar.gz 2>/dev/null || shasum -a 256 -- *.tar.gz) > "$BUILT"
check() { bash "$HERE/platform-built-check.sh" "$@"; }
check "$BUILT" "$BIN" >/dev/null 2>&1 && pass "built check passes tarballs this run built" || fail "built check refused built tarballs"
: > "$T/empty.txt"
if check "$T/empty.txt" "$BIN" >/dev/null 2>&1; then fail "built check passed with an empty list"; else pass "built check refuses when the list is empty"; fi
# A foreign upload under a built name: other bytes, same file name.
REPL="$T/replaced"; cp -R "$BIN" "$REPL"; mktar "$REPL/demo-1.2.3-linux-amd64.tar.gz" "attacker binary"
out="$(check "$BUILT" "$REPL" 2>&1)" && fail "built check passed a replaced asset" || case "$out" in *"not built by this run: demo-1.2.3-linux-amd64.tar.gz"*) pass "built check refuses a replaced asset" ;; *) fail "replaced asset refused wrongly: $out" ;; esac
# Built bytes presented under another platform's name.
REN="$T/renamed"; mkdir "$REN"; cp "$PLIN" "$REN/demo-1.2.3-windows-amd64.tar.gz"
if check "$BUILT" "$REN" >/dev/null 2>&1; then fail "built check passed built bytes under another platform name"; else pass "built check refuses built bytes under another name"; fi
# A tarball that was built but is not listed (list from another run).
printf '%s  %s\n' "$(sha256_file "$PLIN")" "demo-1.2.3-linux-amd64.tar.gz" > "$T/partial.txt"
if check "$T/partial.txt" "$BIN" >/dev/null 2>&1; then fail "built check passed an unlisted tarball"; else pass "built check refuses a tarball missing from the list"; fi
# Garbage and substring lines grant nothing.
printf 'zz  demo-1.2.3-linux-amd64.tar.gz\n%s demo-1.2.3-linux-amd64.tar.gz\n' "$(sha256_file "$PLIN")" > "$T/garbage.txt"
if check "$T/garbage.txt" "$BIN" >/dev/null 2>&1; then fail "built check accepted malformed list lines"; else pass "built check ignores malformed list lines"; fi
# Source tarballs require the same build evidence as platform tarballs.
SRCONLY="$T/srconly"; mkdir "$SRCONLY"; cp "$SRC" "$SRCONLY/"
if check "$T/empty.txt" "$SRCONLY" >/dev/null 2>&1; then fail "built check passed an unlisted source tarball"; else pass "built check refuses an unlisted source tarball"; fi
rc=0; check "$T/nope.txt" "$BIN" >/dev/null 2>&1 || rc=$?
[ "$rc" = 2 ] && pass "built check: a missing list is a usage error, not a pass" || fail "missing list exit $rc"
rc=0; check "$BUILT" "$T/nodir" >/dev/null 2>&1 || rc=$?
[ "$rc" = 2 ] && pass "built check: a missing directory is a usage error" || fail "missing directory exit $rc"
# A file name carrying a line break plus a granted line must not ride on that grant (Opus review).
NL="$T/newline"; mkdir "$NL"
printf 'evil' > "$T/evil.bin"
evsha="$(sha256_file "$T/evil.bin")"
nlname="x"$'\n'"${evsha}"$'\t'"bar-linux-amd64.tar.gz"
cp "$T/evil.bin" "$NL/$nlname"
printf '%s  bar-linux-amd64.tar.gz\n' "$evsha" > "$T/nl.txt"
if check "$T/nl.txt" "$NL" >/dev/null 2>&1; then fail "built check passed a file name with a line break"; else pass "built check refuses a file name with a line break"; fi
# Symlinked entries are read through (the workflow stages symlinks).
LNK="$T/linked"; mkdir "$LNK"; ln -s "$PLIN" "$LNK/demo-1.2.3-linux-amd64.tar.gz"
check "$BUILT" "$LNK" >/dev/null 2>&1 && pass "built check follows symlinks" || fail "built check refused a symlinked built tarball"

# --- the committed interop fixture (P7-PLUG-84 copies it) ----------------------------------------------------------------------
FIX="$HERE/testdata/platform-v1"

# regen_testdata: rebuild the fixture with the throwaway key above (its private half dies with $T).
regen_testdata() {
  local f="$FIX" src plin sig
  rm -rf "$f"; mkdir -p "$f"
  build_release "$T/fx" demo 1.0.0
  cp "$T/fx/demo-1.0.0.tar.gz" "$T/fx/demo-1.0.0-linux-amd64.tar.gz" "$T/fx/releases.json" "$f/"
  cp "$T/test.pub" "$f/fixture.pub"
  chmod 644 "$f/fixture.pub"
  src="$f/demo-1.0.0.tar.gz"; plin="$f/demo-1.0.0-linux-amd64.tar.gz"
  jq -S '.releases.demo |= (del(.platform_checksums["darwin-arm64"]) | del(.platform_signatures["darwin-arm64"]))' "$T/fx/releases.json" > "$f/releases.json"
  sig="$(jq -c '.releases.demo.platform_signatures["linux-amd64"]' "$f/releases.json")"
  jq -nS --arg id "$ID" --arg ssha "$(sha256_file "$src")" --arg psha "$(sha256_file "$plin")" --argjson sig "$sig" \
    --argjson ssig "$(jq -c '.releases.demo.release_signature' "$f/releases.json")" '{
      "contract": "plugins.release-signature v1.1",
      "public_key": "fixture.pub",
      "key_id": $id,
      "slug": "demo", "version": "1.0.0", "platform": "linux-amd64",
      "source_tarball": "demo-1.0.0.tar.gz", "source_sha256": $ssha, "source_signature": $ssig,
      "platform_tarball": "demo-1.0.0-linux-amd64.tar.gz", "platform_sha256": $psha, "platform_signature": $sig,
      "platform_message": "nself-plugin-bin-v1\\n<slug>\\n<version>\\n<platform>\\n<sha256 hex of the platform tarball>\\n",
      "cases": [
        {"name": "valid", "expect": "ok"},
        {"name": "other platform", "platform": "linux-arm64", "expect": "fail"},
        {"name": "other version", "version": "1.0.1", "expect": "fail"},
        {"name": "other slug", "slug": "other", "expect": "fail"},
        {"name": "flipped byte", "tarball_append_byte": true, "expect": "fail"},
        {"name": "source signature as platform signature", "signature": "source", "expect": "fail"}
      ]}' > "$f/vectors.json"
  cat > "$f/README.md" <<'EOF'
Interop fixture for contract plugins.release-signature v1.1 (platform signatures). Made by
scripts/release/platform-signatures-test.sh --regen-testdata with scripts/release/sign.sh and a THROWAWAY key (fixture.pub is its
public half; the private half was discarded). Not a release key: it is not in scripts/release/keys/ and no CLI pins it.

- demo-1.0.0.tar.gz / demo-1.0.0-linux-amd64.tar.gz: stub tarballs. releases.json: the release-data rows for them.
- vectors.json: slug, version, platform, tarball sha256, signature object, and cases (each overrides fields of the vector and says
  whether the signature must verify). A verifier recomputes the message
  `nself-plugin-bin-v1\n<slug>\n<version>\n<platform>\n<sha256 hex of the platform tarball>\n` from the case, and verifies the raw
  Ed25519 signature (base64 `sig`) with fixture.pub. The `tarball_append_byte` case verifies the signature over the sha256 of the
  tarball with one byte appended; `signature: source` uses `source_signature` as the platform signature.
EOF
  echo "regenerated $f (key id $ID)"
}
if [ "${1:-}" = "--regen-testdata" ]; then regen_testdata; exit 0; fi

if [ -f "$FIX/vectors.json" ]; then
  FXPUB="$FIX/fixture.pub"
  if verify "$FIX" "$FXPUB" >/dev/null 2>&1; then pass "fixture verifies with its own public key"; else fail "fixture does not verify: $(verify "$FIX" "$FXPUB" 2>&1)"; fi
  for k in "$HERE"/keys/*.pub; do
    [ -e "$k" ] || continue
    if verify "$FIX" "$k" >/dev/null 2>&1; then fail "fixture verifies against committed key $(basename "$k")"; else pass "fixture refused by committed key $(basename "$k")"; fi
  done
  # Every vector case, recomputed from first principles with openssl.
  fx() { jq -r "$1" "$FIX/vectors.json"; }
  ncases="$(fx '.cases | length')"
  i=0
  while [ "$i" -lt "$ncases" ]; do
    cname="$(fx ".cases[$i].name")"; want="$(fx ".cases[$i].expect")"
    slug="$(fx ".cases[$i].slug // .slug")"; ver="$(fx ".cases[$i].version // .version")"; plat="$(fx ".cases[$i].platform // .platform")"
    cp "$FIX/$(fx .platform_tarball)" "$T/vec.tar.gz"
    [ "$(fx ".cases[$i].tarball_append_byte // false")" != "true" ] || printf 'x' >> "$T/vec.tar.gz"
    printf 'nself-plugin-bin-v1\n%s\n%s\n%s\n%s\n' "$slug" "$ver" "$plat" "$(sha256_file "$T/vec.tar.gz")" > "$T/vec.msg"
    if [ "$(fx ".cases[$i].signature // \"platform\"")" = "source" ]; then s="$(fx .source_signature.sig)"; else s="$(fx .platform_signature.sig)"; fi
    printf '%s' "$s" | "$O" base64 -d -A > "$T/vec.sig"
    if "$O" pkeyutl -verify -rawin -pubin -inkey "$FXPUB" -in "$T/vec.msg" -sigfile "$T/vec.sig" >/dev/null 2>&1; then got=ok; else got=fail; fi
    [ "$got" = "$want" ] && pass "fixture vector '$cname' is $want" || fail "fixture vector '$cname': wanted $want, got $got"
    i=$((i + 1))
  done
else
  fail "scripts/release/testdata/platform-v1/vectors.json is missing (regenerate with --regen-testdata)"
fi

[ "$fails" = 0 ] && echo "PASS platform-signatures" || { echo "FAILED: $fails case(s)"; exit 1; }
